const raw = $input.first().json.output || $input.first().json.text || '';
const md = raw.replace(/\\n/g, '\n'); // handles literal "\n" text too

const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let html = '';
let inList = false;
const closeList = () => { if (inList) { html += '</ul>'; inList = false; } };

for (let line of md.split('\n')) {
  line = line.trim();
  if (!line) { closeList(); continue; }

  const t = esc(line).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');

  if (t.startsWith('## ')) {
    closeList();
    html += `<h3 style="margin:18px 0 8px;color:#1a1a1a;">${t.slice(3)}</h3>`;
  } else if (/^([-*]|\d+\.)\s/.test(t)) {
    if (!inList) { html += '<ul style="margin:0 0 12px;padding-left:20px;">'; inList = true; }
    html += `<li style="margin-bottom:6px;">${t.replace(/^([-*]|\d+\.)\s/, '')}</li>`;
  } else {
    closeList();
    html += `<p style="margin:0 0 12px;line-height:1.5;">${t}</p>`;
  }
}
closeList();

const body = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#333;max-width:600px;">${html}</div>`;

return [{ json: { html: body, subject: `Email Action Summary - ${$now.toFormat('dd LLL yyyy')}` } }];
